import type { EnvSchemaAsStrings } from "../../../env";

/**
 * Env for the events side (apps/server, packages/db), read from `process.env`.
 *
 * Nothing is validated here. The rules (required, URL shapes, defaults) live in
 * the repo-root `.env.schema`, and varlock enforces them where a process starts:
 * every package script runs through `varlock run`, which validates and injects
 * before any code loads. The values are typed from the same schema
 * (`env.d.ts`, generated by varlock). They are read through `schemaEnv`, not
 * `process.env`: varlock cannot augment `NodeJS.ProcessEnv` while
 * `worker-configuration.d.ts` (wrangler types) already does, so
 * `process.env` itself only knows the Worker's names.
 *
 * Read once at import, as before. Empty strings count as unset.
 */
const schemaEnv = process.env as unknown as EnvSchemaAsStrings;

const read = (value: string | undefined) => (value === "" ? undefined : value);

export const env = {
	DATABASE_URL: schemaEnv.DATABASE_URL,
	CORS_ORIGIN: schemaEnv.CORS_ORIGIN,
	NODE_ENV: read(schemaEnv.NODE_ENV) ?? "development",
};
